const KEY='nationSu';const LOGO_DATA='data:image/png;base64,';
function readStored(key,fallback,store=localStorage){try{const raw=store.getItem(key);return raw?JSON.parse(raw):fallback}catch(error){console.warn(`Invalid saved data ignored for ${key}.`,error);return fallback}}
const readArray=key=>{const value=readStored(key,[]);return Array.isArray(value)?value.filter(item=>item&&typeof item==='object'):[]};
const readObject=(key,fallback={},store=localStorage)=>{const value=readStored(key,fallback,store);return value&&typeof value==='object'&&!Array.isArray(value)?value:fallback};
const normalizePhoneStatus=value=>{const status=String(value||'').trim().toLowerCase();if(!status||['in stock','instock','in-stock','available'].includes(status))return 'In Stock';if(status==='sold')return 'Sold';return String(value).trim()};
const isInStock=phone=>normalizePhoneStatus(phone?.status)==='In Stock';
const state={page:'dashboard',phones:readArray('nationSuPhones'),sales:readArray('nationSuSales'),customers:readArray('nationSuCustomers'),expenses:readArray('nationSuExpenses'),tradeins:readArray('nationSuTradeins'),warranties:readArray('nationSuWarranties'),users:readArray('nationSuUsers'),purchases:readArray('nationSuPurchases'),installments:readArray('nationSuInstallments'),user:readObject('nationSuUser',null,sessionStorage)};
state.phones.forEach(phone=>phone.status=normalizePhoneStatus(phone.status));
const SALES_PERSONS=['Chit Su Su Thwe','Thi Phyu Ye Win','Thoon Hsu Han','Khine Thazin Phue','Kaung Thant'];
const defaultInvoiceSettings={shopName:'i-Nation Su',subtitle:'iPhone Second • Sales Invoice',phone:'+959941999600',address:'',footer:'Thank you for your purchase.',showLogo:true,showCustomerPhone:true,showIMEI:true,showPayment:true,showSalesPerson:true};
let invoiceSettings=Object.assign({},defaultInvoiceSettings,readObject('nationSuInvoiceSettings'));
function saveInvoiceSettings(){localStorage.setItem('nationSuInvoiceSettings',JSON.stringify(invoiceSettings))}

const app=document.getElementById('app'),modal=document.getElementById('modal'),invoiceModal=document.getElementById('invoiceModal');
const money=n=>Number(n||0).toLocaleString('en-US')+' Ks'; const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const today=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const dateKey=v=>{if(v===null||v===undefined||v==='')return ''; const raw=String(v).trim(); if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return raw; if(/^\d+(\.\d+)?$/.test(raw)){const n=Number(raw); if(n>20000&&n<100000){const d=new Date(Date.UTC(1899,11,30)+Math.round(n)*86400000); return d.toISOString().slice(0,10);}} const m=raw.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/); if(m){const d=new Date(Date.UTC(+m[3],+m[2]-1,+m[1])); return isNaN(d)?'':d.toISOString().slice(0,10)} const d=new Date(raw);return isNaN(d)?'':new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const displayDate=v=>{const k=dateKey(v); if(!k)return '-'; const [y,m,d]=k.split('-'); return `${d}/${m}/${y}`};
const save=()=>{localStorage.setItem('nationSuPhones',JSON.stringify(state.phones));localStorage.setItem('nationSuSales',JSON.stringify(state.sales));localStorage.setItem('nationSuCustomers',JSON.stringify(state.customers));localStorage.setItem('nationSuExpenses',JSON.stringify(state.expenses));localStorage.setItem('nationSuTradeins',JSON.stringify(state.tradeins));localStorage.setItem('nationSuWarranties',JSON.stringify(state.warranties));localStorage.setItem('nationSuUsers',JSON.stringify(state.users));localStorage.setItem('nationSuPurchases',JSON.stringify(state.purchases));localStorage.setItem('nationSuInstallments',JSON.stringify(state.installments));};
function admin(){return state.user?.role==='admin'}
function go(p){state.page=p;render()}
document.addEventListener('click',e=>{const nav=e.target.closest&&e.target.closest('.nav-btn[data-page]');if(nav){e.preventDefault();go(nav.dataset.page);return}const a=e.target.closest&&e.target.closest('[data-invoice-id]');if(a){e.preventDefault();openInvoiceById(a.dataset.invoiceId);return}const h=e.target.closest&&e.target.closest('[data-hi]');if(h){e.preventDefault();openInvoiceById(h.dataset.hi)}});
function shell(){document.getElementById('loginScreen').classList.toggle('hidden',!!state.user);document.getElementById('systemShell').classList.toggle('hidden',!state.user)}
function render(){shell();if(!state.user)return;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));({dashboard:dashboard,inventory:inventory,sales:sales,cashIncome:cashIncome,customers:customers,expenses:expenses,reports:reports,tradein:tradein,warranty:warranty,users:users,backup:backup,purchases:purchases,settings:settings}[state.page]||dashboard)()}
function header(title,sub='',actions=''){return `<div class="topbar"><div class="page-title"><img class="page-logo" src="logo.png" alt="i-Nation Su"><div><h1>${title}</h1>${sub?`<div class="muted">${sub}</div>`:''}</div></div><div class="actions">${actions}</div></div>`}
function dashboard(){const stock=state.phones.filter(p=>p.status==='In Stock').length,sales=state.sales.reduce((a,s)=>a+Number(s.finalPrice||0),0),profit=state.sales.reduce((a,s)=>a+Number(s.profit||0),0),exp=state.expenses.reduce((a,e)=>a+Number(e.amount||0),0);app.innerHTML=header('Dashboard','i-Nation Su — Second-hand iPhone Shop')+`<div class="cards"><div class="card"><h3>Total Stock</h3><p>${stock}</p></div><div class="card"><h3>Total Sales</h3><p>${money(sales)}</p></div><div class="card"><h3>Sold Phones</h3><p>${state.sales.length}</p></div>${admin()?`<div class="card sensitive"><h3>Net Profit</h3><p>${money(profit-exp)}</p></div>`:''}</div><div class="grid2"><div class="card"><h3>Quick Actions</h3><div class="actions"><button class="primary" onclick="go('inventory')">＋ Add Stock</button><button class="secondary" onclick="go('sales')">💰 New Sale</button><button class="secondary" onclick="go('tradein')">🔄 Trade-in</button><button class="secondary" onclick="go('expenses')">💸 Expense</button></div></div><div class="card"><h3>Today</h3><p>${state.sales.filter(s=>dateKey(s.dateISO||s.date)===today()).length} sales</p><p class="muted">${state.tradeins.filter(t=>dateKey(t.date)===today()).length} trade-ins</p></div></div>`}
function batteryValue(v){if(v===null||v===undefined||v==='')return null;let n;if(typeof v==='string'){const t=v.trim().replace('%','');n=Number(t)}else n=Number(v);if(!Number.isFinite(n))return null;if(n>0&&n<=1)n*=100;return Math.max(1,Math.min(100,Math.round(n)))}
function batteryDisplay(v){const n=batteryValue(v);return n===null?'-':String(n)}
state.phones.forEach(p=>{const b=batteryValue(p.battery);if(b!==null)p.battery=b});state.tradeins.forEach(t=>{const b=batteryValue(t.battery);if(b!==null)t.battery=b});
function inventory(){const stockEntries=state.phones.map((p,i)=>({p,i})).filter(x=>(x.p.status||'In Stock')==='In Stock');const rows=stockEntries.map(({p,i})=>`<tr data-index="${i}"><td>${admin()?`<input class="stock-check" type="checkbox" data-index="${i}">`:''}</td><td>${esc(p.model)}</td><td>${esc(p.storage)}</td><td>${esc(p.region||'-')}</td><td>${esc(p.supplier||'-')}</td><td>${esc(displayDate(p.purchaseDate))}</td><td>${esc(p.color||'-')}</td><td>${esc(p.imei)}</td><td>${batteryDisplay(p.battery)}%</td><td>${money(p.purchasePrice)}</td><td>${money(p.sellingPrice)}</td><td><span class="badge">${esc(p.status||'In Stock')}</span></td><td>${admin()?`<button class="secondary small" onclick="editPhone(${i})">Edit</button> <button class="secondary small" onclick="printBarcode(${i})">🏷️ Sticker</button> <button class="icon-btn" onclick="delPhone(${i})">🗑️</button>`:`<button class="secondary small" onclick="printBarcode(${i})">🏷️ Sticker</button>`}</td></tr>`).join('');const bulk=admin()?`<button class="secondary" id="selectAllStock">☑️ Select All</button><button class="danger" id="bulkDeleteStock">🗑️ Delete Selected</button>`:'';app.innerHTML=header('Inventory','Stock, IMEI, Supplier, Purchase Date, Region and pricing',`${bulk}<button class="secondary" onclick="printAllBarcodes()">🏷️ Print All Stickers</button><button class="secondary" id="imp">📥 Import Excel</button><button class="secondary" onclick="exportInventory()">📤 Export Excel</button><button class="secondary" onclick="templateInventory()">📄 Template</button><button class="primary" onclick="phoneForm()">＋ Add iPhone</button><input id="file" type="file" accept=".xlsx,.xls" hidden>`)+`<div class="toolbar"><input id="invSearch" class="search" placeholder="Search model / IMEI / region / supplier / status..."></div><div class="table-wrap">${rows?`<table><thead><tr><th>${admin()?'<input id="selectAllHeader" type="checkbox" title="Select all">':''}</th><th>Model</th><th>Storage</th><th>Region</th><th>Supplier</th><th>Purchase Date</th><th>Color</th><th>IMEI</th><th>Battery</th><th>Buy</th><th>Sell</th><th>Status</th><th>Actions</th></tr></thead><tbody id="invRows">${rows}</tbody></table>`:`<div class="empty">No inventory yet.</div>`}</div>`;document.getElementById('imp').onclick=()=>document.getElementById('file').click();document.getElementById('file').onchange=e=>e.target.files[0]&&importInventory(e.target.files[0]);document.getElementById('invSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#invRows tr').forEach(tr=>{const i=+tr.dataset.index;tr.style.display=JSON.stringify(state.phones[i]).toLowerCase().includes(q)?'':'none'})};if(admin()){const checks=()=>Array.from(document.querySelectorAll('.stock-check'));const sync=()=>{const visible=checks().filter(c=>c.closest('tr').style.display!=='none');const selected=checks().filter(c=>c.checked);const all=document.getElementById('selectAllHeader');if(all)all.checked=visible.length>0&&visible.every(c=>c.checked);};document.getElementById('selectAllStock').onclick=()=>{checks().forEach(c=>c.checked=true);sync()};document.getElementById('selectAllHeader').onchange=e=>{checks().filter(c=>c.closest('tr').style.display!=='none').forEach(c=>c.checked=e.target.checked);sync()};checks().forEach(c=>c.onchange=sync);document.getElementById('bulkDeleteStock').onclick=()=>{const ids=checks().filter(c=>c.checked).map(c=>+c.dataset.index);if(!ids.length)return alert('ဖျက်မယ့် Stock ကို အရင်ရွေးပါ။');if(!confirm(`${ids.length} ခုသော Stock ကို တခါတည်း ဖျက်မလား?\nဖျက်ပြီးပါက ပြန်ယူရန် Backup မရှိလျှင် မရနိုင်ပါ။`))return;state.phones=state.phones.filter((_,i)=>!ids.includes(i));save();inventory()}}}
function phoneForm(i=null){const p=i==null?{}:state.phones[i];openModal(i==null?'Add iPhone':'Edit iPhone',`<form id="f"><div class="form-grid"><label>Model<input name="model" required value="${esc(p.model)}"></label><label>Region<input name="region" placeholder="Yangon / Mandalay / ..." value="${esc(p.region)}"></label><label>Supplier<input name="supplier" placeholder="Supplier name" value="${esc(p.supplier)}"></label><label>Purchase Date<input name="purchaseDate" type="date" value="${esc(p.purchaseDate||today())}"></label><label>Storage<select name="storage">${['64GB','128GB','256GB','512GB','1TB'].map(x=>`<option ${p.storage===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Color<input name="color" value="${esc(p.color)}"></label><label>IMEI<input name="imei" required value="${esc(p.imei)}"></label><label>Battery Health %<input name="battery" type="number" min="1" max="100" step="1" required value="${p.battery!=null?batteryDisplay(p.battery):''}"></label><label>Condition<select name="condition">${['10/10','9/10','8/10','7/10','6/10'].map(x=>`<option ${p.condition===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Box<select name="box"><option ${p.box==='ပါ'?'selected':''}>ပါ</option><option ${p.box==='မပါ'?'selected':''}>မပါ</option></select></label><label>Accessories<select name="accessories"><option ${p.accessories==='ပါ'?'selected':''}>ပါ</option><option ${p.accessories==='မပါ'?'selected':''}>မပါ</option></select></label><label>Purchase Price (Ks)<input name="purchasePrice" type="number" min="0" required value="${p.purchasePrice??''}"></label><label>Selling Price (Ks)<input name="sellingPrice" type="number" min="0" required value="${p.sellingPrice??''}"></label></div><button class="primary">Save</button></form>`);document.getElementById('f').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.battery=batteryValue(x.battery);x.purchasePrice=+x.purchasePrice;x.sellingPrice=+x.sellingPrice;x.purchaseDate=dateKey(x.purchaseDate||p.purchaseDate||today())||today();x.supplier=(x.supplier||'').trim();x.status=p.status||'In Stock';if(i==null)state.phones.push(x);else state.phones[i]=x;save();closeModal();inventory()}}
function delPhone(i){if(confirm('Delete this phone?')){state.phones.splice(i,1);save();inventory()}}
function editPhone(i){if(admin())phoneForm(i)}
function sales(){const stock=state.phones.filter(p=>p.status==='In Stock'),rows=state.sales.slice().reverse().map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.model)} ${esc(s.storage||'')}</td><td>${esc(s.imei)}</td><td>${esc(s.customer||'-')}</td><td>${esc(s.salesPerson||'-')}</td><td>${money(s.finalPrice)}</td>${admin()?`<td>${money(s.profit)}</td>`:''}<td>${esc(s.paymentType)} ${s.paymentDetail?'— '+esc(s.paymentDetail):''}</td><td><button type="button" class="secondary small invoice-btn" data-invoice-id="${esc(s.id)}" onclick="openInvoiceById(this.dataset.invoiceId)">🧾 Invoice</button></td></tr>`).join('');app.innerHTML=header('Sales','Sell from current stock',`<button class="primary" ${stock.length?'':'disabled'} onclick="saleForm()">＋ Sell iPhone</button>`)+`<div class="table-wrap">${rows?`<table><thead><tr><th>Date</th><th>Phone</th><th>IMEI</th><th>Customer</th><th>Sales Person</th><th>Total</th>${admin()?'<th>Profit</th>':''}<th>Payment</th><th></th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="empty">No sales yet.</div>`}</div>${!admin()?'<div class="notice">Profit information is hidden for Sales Staff.</div>':''}`}
function paymentOptions(type){if(type==='MMQR')return ['KBZPay','WavePay','AYA Pay','CB Pay','UAB Pay','OK$','Other MMQR'];if(type==='Banking'||type==='MPU')return ['KBZ Bank','AYA Bank','CB Bank','UAB Bank','Yoma Bank','MAB Bank','AGD Bank','Other Bank'];return ['Cash']}
function saleForm(){const stock=state.phones.filter(p=>p.status==='In Stock');openModal('Sell iPhone',`<form id="sf"><div class="form-grid"><label>Phone<select id="sp" name="phone">${stock.map(p=>`<option value="${state.phones.indexOf(p)}">${esc(p.model)} — ${esc(p.storage)} — ${esc(p.imei)}</option>`).join('')}</select></label><label>Sales Person<select name="salesPerson" required>${SALES_PERSONS.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Customer Name<input name="customer"></label><label>Customer Phone<input name="customerPhone"></label><label>Selling Price<input id="sprice" name="price" type="number" required value="${stock[0]?.sellingPrice||0}"></label><label>Discount<input name="discount" type="number" value="0"></label><label>Payment Type<select id="pt" name="paymentType"><option>Cash</option><option>Cash Down</option><option>MMQR</option><option>Banking</option><option>MPU</option><option>Installment</option></select></label><label id="paymentDetailWrap">Payment Detail<select id="pd" name="paymentDetail"><option>Cash</option></select></label><label id="depositWrap" style="display:none">Deposit (Ks)<input id="deposit" name="deposit" type="number" min="0" value="0"></label><label id="dueWrap" style="display:none">Next Payment Due Date<input id="dueDate" name="dueDate" type="date"></label><label>Payment Note<input name="paymentNote"></label></div><div id="installmentHint" class="notice" style="display:none">Installment ရွေးထားပါက Deposit ကို အရင်လက်ခံငွေအဖြစ် Cash Income ထဲသို့ ထည့်ပြီး ကျန် Balance ကို Due Date နဲ့ ချိတ်ထားပါမယ်။</div><button class="primary">Complete Sale</button></form>`);const upd=()=>{const type=document.getElementById('pt').value,isInst=type==='Installment',isDown=type==='Cash Down',needsDeposit=isInst||isDown;document.getElementById('pd').innerHTML=paymentOptions(needsDeposit?'Cash':type).map(x=>`<option>${x}</option>`).join('');document.getElementById('depositWrap').style.display=needsDeposit?'block':'none';document.getElementById('dueWrap').style.display=isInst?'block':'none';document.getElementById('installmentHint').style.display=isInst?'block':'none';if(needsDeposit){const price=+document.getElementById('sprice').value||0,disc=+document.querySelector('[name=discount]').value||0,total=Math.max(0,price-disc);document.getElementById('deposit').max=total;document.getElementById('deposit').placeholder='0 - '+total}};document.getElementById('pt').onchange=upd;document.getElementById('sp').onchange=e=>document.getElementById('sprice').value=state.phones[+e.target.value].sellingPrice;document.querySelector('[name=discount]').oninput=upd;document.getElementById('sf').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),p=state.phones[+f.phone],price=+f.price,discount=+f.discount||0,finalPrice=Math.max(0,price-discount),isInst=f.paymentType==='Installment',isDown=f.paymentType==='Cash Down',deposit=Math.max(0,Math.min(finalPrice,+f.deposit||0)),balance=Math.max(0,finalPrice-deposit);if(isInst&&!f.dueDate&&balance>0)return alert('Installment Due Date ထည့်ပေးပါ။');if(isInst&&deposit>finalPrice)return alert('Deposit သည် Total ထက် မကျော်ရပါ။');const profit=finalPrice-(+p.purchasePrice||0),now=new Date(),needsDeposit=isInst||f.paymentType==='Cash Down';p.status='Sold';const s={id:'INV-'+Date.now(),date:now.toLocaleString(),dateISO:now.toISOString(),model:p.model,storage:p.storage,color:p.color||'',battery:batteryValue(p.battery),condition:p.condition||'',box:p.box||'',accessories:p.accessories||'',imei:p.imei,customer:f.customer||'',customerPhone:f.customerPhone||'',salesPerson:f.salesPerson||'',purchasePrice:+p.purchasePrice||0,sellingPrice:price,discount,finalPrice,profit,paymentType:f.paymentType,paymentDetail:f.paymentDetail,paymentNote:f.paymentNote||'',deposit:needsDeposit?deposit:finalPrice,balance:needsDeposit?balance:0,dueDate:isInst?(f.dueDate||''):'',installmentStatus:isInst?(balance>0?'Pending':'Paid'):(isDown?(balance>0?'Cash Down':'Paid'):'Paid')};state.sales.push(s);if(isInst){state.installments.push({id:'INS-'+Date.now(),saleId:s.id,invoiceId:s.id,customer:s.customer,customerPhone:s.customerPhone,total:finalPrice,deposit,balance,dueDate:s.dueDate,status:balance>0?'Pending':'Paid',payments:deposit?[{date:now.toISOString(),amount:deposit,note:'Deposit'}]:[]})}upsertCustomer(s);save();closeModal();sales();openInvoice(s)}}
function cashIncome(){const salesIncome=state.sales.flatMap(s=>{if(s.paymentType==='Installment'){const ins=state.installments.find(x=>x.saleId===s.id);return ins?(ins.payments||[]).map((p,i)=>({id:ins.id+'-'+i,date:p.date?new Date(p.date).toLocaleString():'',customer:ins.customer||'Walk-in',type:i===0&&p.note==='Deposit'?'Deposit':'Installment',amount:+p.amount||0,ref:ins.invoiceId,status:'Received'})):[]};if(s.paymentType==='Cash Down')return [{id:s.id,date:s.date,customer:s.customer||'Walk-in',type:'Cash Down Deposit',amount:+s.deposit||0,ref:s.id,status:'Received'}];return [{id:s.id,date:s.date,customer:s.customer||'Walk-in',type:'Sale',amount:+s.finalPrice||0,ref:s.id,status:'Received'}]});const due=state.installments.slice().sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)));const rows=due.map(ins=>`<tr><td>${esc(ins.dueDate||'-')}</td><td>${esc(ins.customer||'Walk-in')}</td><td>${esc(ins.invoiceId)}</td><td>${money(ins.total)}</td><td>${money(ins.deposit)}</td><td>${money(ins.balance)}</td><td><span class="badge">${esc(ins.status)}</span></td><td>${ins.balance>0?`<button class="primary small" onclick="collectInstallment('${ins.id}')">＋ Collect</button>`:'Paid'}</td></tr>`).join('');const incomeRows=salesIncome.slice().reverse().map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.customer)}</td><td>${esc(x.type)}</td><td>${money(x.amount)}</td><td>${esc(x.ref)}</td></tr>`).join('');const todayStr=today();const todayDue=due.filter(x=>x.balance>0&&x.dueDate===todayStr).length;const overdue=due.filter(x=>x.balance>0&&x.dueDate&&x.dueDate<todayStr).length;app.innerHTML=header('Cash Income','Cash received + Installment collection',`<span class="notice">Due today: ${todayDue} • Overdue: ${overdue}</span>`)+`<div class="cards"><div class="card"><h3>Cash Received</h3><p>${money(salesIncome.reduce((a,x)=>a+x.amount,0))}</p></div><div class="card"><h3>Outstanding Installment</h3><p>${money(due.reduce((a,x)=>a+x.balance,0))}</p></div></div><div class="card"><h3>Installment Schedule</h3><div class="table-wrap">${rows?`<table><thead><tr><th>Due Date</th><th>Customer</th><th>Invoice</th><th>Total</th><th>Deposit</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No installment sales.</div>'}</div></div><div class="card"><h3>Cash Income History</h3><div class="table-wrap">${incomeRows?`<table><thead><tr><th>Date</th><th>Customer</th><th>Type</th><th>Amount</th><th>Reference</th></tr></thead><tbody>${incomeRows}</tbody></table>`:'<div class="empty">No income yet.</div>'}</div></div>`}
function collectInstallment(id){const ins=state.installments.find(x=>x.id===id);if(!ins||ins.balance<=0)return;openModal('Collect Installment',`<form id="icf"><div class="form-grid"><label>Customer<input value="${esc(ins.customer||'Walk-in')}" disabled></label><label>Due Date<input value="${esc(ins.dueDate||'')}" disabled></label><label>Balance<input value="${money(ins.balance)}" disabled></label><label>Collect Amount (Ks)<input name="amount" type="number" min="1" max="${ins.balance}" value="${ins.balance}" required></label><label>Payment Date<input name="date" type="date" value="${today()}" required></label><label>Note<input name="note" value="Installment Payment"></label></div><button class="primary">Save Collection</button></form>`);document.getElementById('icf').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),amt=Math.min(ins.balance,+f.amount||0);if(amt<=0)return alert('Amount ထည့်ပေးပါ။');ins.payments=ins.payments||[];ins.payments.push({date:new Date(f.date+'T12:00:00').toISOString(),amount:amt,note:f.note||'Installment Payment'});ins.deposit=+ins.deposit||0;ins.balance=Math.max(0,ins.balance-amt);ins.status=ins.balance===0?'Paid':'Pending';const sale=state.sales.find(s=>s.id===ins.saleId);if(sale){sale.deposit=+sale.deposit||0;sale.deposit+=amt;sale.balance=ins.balance;sale.installmentStatus=ins.status}save();closeModal();cashIncome()}}

function upsertCustomer(s){if(!s.customer&&!s.customerPhone)return;const c=state.customers.find(x=>(s.customerPhone&&x.phone===s.customerPhone)||(!s.customerPhone&&x.name.toLowerCase()===s.customer.toLowerCase()));if(c){if(s.customer)c.name=s.customer;if(s.customerPhone)c.phone=s.customerPhone}else state.customers.push({id:'CUS-'+Date.now(),name:s.customer||'Unknown',phone:s.customerPhone||'',address:'',note:''})}
function customers(){const q=String(document.getElementById('cq')?.value||'').toLowerCase();const list=state.customers.filter(c=>JSON.stringify(c).toLowerCase().includes(q));app.innerHTML=header('Customers','Customer records and purchase history',`<button class="primary" onclick="customerForm()">＋ Add Customer</button>`)+`<div class="toolbar"><input id="cq" class="search" placeholder="Search name / phone..." value="${esc(q)}"></div><div class="table-wrap">${list.length?`<table><thead><tr><th>Name</th><th>Phone</th><th>Address</th><th>Purchases</th><th>Total Spent</th><th>Actions</th></tr></thead><tbody>${list.map(c=>{const h=state.sales.filter(s=>(c.phone&&s.customerPhone===c.phone)||(!c.phone&&s.customer?.toLowerCase()===c.name.toLowerCase()));return `<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${esc(c.address)}</td><td>${h.length}</td><td>${money(h.reduce((a,s)=>a+s.finalPrice,0))}</td><td><button class="secondary small" onclick="customerHistory('${c.id}')">View</button> <button class="secondary small" onclick="customerForm('${c.id}')">Edit</button>${admin()?` <button class="icon-btn" onclick="delCustomer('${c.id}')">🗑️</button>`:''}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No customers yet.</div>'}</div><div id="ch"></div>`;document.getElementById('cq').oninput=customers}
function customerForm(id=null){const c=state.customers.find(x=>x.id===id)||{};openModal(id?'Edit Customer':'Add Customer',`<form id="cf"><div class="form-grid"><label>Name<input name="name" required value="${esc(c.name)}"></label><label>Phone<input name="phone" value="${esc(c.phone)}"></label><label>Address<input name="address" value="${esc(c.address)}"></label><label>Note<input name="note" value="${esc(c.note)}"></label></div><button class="primary">Save</button></form>`);document.getElementById('cf').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(id)Object.assign(c,x);else state.customers.push({id:'CUS-'+Date.now(),...x});save();closeModal();customers()}}
function delCustomer(id){if(confirm('Delete customer?')){state.customers=state.customers.filter(c=>c.id!==id);save();customers()}}
function customerHistory(id){const c=state.customers.find(x=>x.id===id),h=state.sales.filter(s=>(c.phone&&s.customerPhone===c.phone)||(!c.phone&&s.customer?.toLowerCase()===c.name.toLowerCase()));document.getElementById('ch').innerHTML=`<div class="card"><h2>${esc(c.name)}</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Phone</th><th>Total</th><th>Payment</th><th></th></tr></thead><tbody>${h.map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.model)} ${esc(s.imei)}</td><td>${money(s.finalPrice)}</td><td>${esc(s.paymentType)}</td><td><button type="button" class="secondary small invoice-btn" data-hi="${esc(s.id)}" onclick="openInvoiceById(this.dataset.hi)">Invoice</button></td></tr>`).join('')}</tbody></table></div></div>`}
function expenses(){const rows=state.expenses.slice().reverse().map((e,i)=>`<tr><td>${esc(e.date)}</td><td>${esc(e.type)}</td><td>${esc(e.description)}</td><td>${money(e.amount)}</td><td>${esc(e.paymentType)}</td><td>${admin()?`<button class="secondary small" onclick="expenseForm(${state.expenses.indexOf(e)})">Edit</button> <button class="icon-btn" onclick="delExpense(${state.expenses.indexOf(e)})">🗑️</button>`:''}</td></tr>`).join('');app.innerHTML=header('Expenses','Shop expenses and operating costs',admin()?`<button class="primary" onclick="expenseForm()">＋ Add Expense</button>`:'')+`<div class="table-wrap">${rows?`<table><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Amount</th><th>Payment</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No expenses recorded.</div>'}</div>`}
function expenseForm(i=null){if(!admin())return;const e=i==null?{}:state.expenses[i];openModal(i==null?'Add Expense':'Edit Expense',`<form id="ef"><div class="form-grid"><label>Date<input name="date" type="date" required value="${e.date||today()}"></label><label>Expense Type<select name="type">${['Shop Rent','Electricity','Internet','Salary','Delivery','Repair','Marketing','Other'].map(x=>`<option ${e.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Description<input name="description" value="${esc(e.description)}"></label><label>Amount (Ks)<input name="amount" type="number" min="0" required value="${e.amount||''}"></label><label>Payment Method<select name="paymentType"><option>Cash</option><option>MMQR</option><option>Banking</option><option>MPU</option></select></label><label>Note<input name="note" value="${esc(e.note)}"></label></div><button class="primary">Save</button></form>`);document.getElementById('ef').onsubmit=x=>{x.preventDefault();const n=Object.fromEntries(new FormData(x.target));n.amount=+n.amount;n.id=e.id||'EXP-'+Date.now();if(i==null)state.expenses.push(n);else state.expenses[i]=n;save();closeModal();expenses()}}
function delExpense(i){if(confirm('Delete expense?')){state.expenses.splice(i,1);save();expenses()}}
function reports(){const s=state.sales,e=state.expenses;app.innerHTML=header('Reports','Financial and payment reports',`<button class="secondary" onclick="exportReport()">📤 Export Excel</button><button class="primary" onclick="exportReportPDF()">📄 Export PDF</button>`)+`<div class="toolbar"><select id="rf"><option value="today">Today</option><option value="week">This Week</option><option value="month" selected>This Month</option><option value="all">All Time</option><option value="custom">Custom Date</option></select><input id="from" type="date"><input id="to" type="date"><button class="primary" id="apply">Apply</button></div><div id="reportBody"></div>`;document.getElementById('apply').onclick=()=>reportBody();document.getElementById('rf').onchange=e=>{const c=e.target.value==='custom';document.getElementById('from').style.display=c?'block':'none';document.getElementById('to').style.display=c?'block':'none'};document.getElementById('from').style.display='none';document.getElementById('to').style.display='none';reportBody()}
function range(){const mode=document.getElementById('rf')?.value||'month',t=today();if(mode==='all')return [null,null];if(mode==='today')return [t,t];const d=new Date();if(mode==='month')return [new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10),t];if(mode==='week'){const day=d.getDay()||7;d.setDate(d.getDate()-day+1);return [d.toISOString().slice(0,10),t]}return [document.getElementById('from').value||t,document.getElementById('to').value||t]}
function inRange(x,r){const k=dateKey(x);return (!r[0]||k>=r[0])&&(!r[1]||k<=r[1])}
function reportBody(){const r=range(),ss=state.sales.filter(s=>inRange(s.dateISO||s.date,r)),ee=state.expenses.filter(e=>inRange(e.date,r)),salesTotal=ss.reduce((a,s)=>a+s.finalPrice,0),cost=ss.reduce((a,s)=>a+s.purchasePrice,0),gross=salesTotal-cost,ex=ee.reduce((a,x)=>a+x.amount,0),net=gross-ex;const pay=['Cash','MMQR','Banking','MPU','Installment'].map(p=>[p,ss.filter(s=>s.paymentType===p).reduce((a,s)=>a+s.finalPrice,0)]);document.getElementById('reportBody').innerHTML=`<div class="cards"><div class="card"><h3>Total Sales</h3><p>${money(salesTotal)}</p></div>${admin()?`<div class="card"><h3>Purchase Cost</h3><p>${money(cost)}</p></div><div class="card"><h3>Gross Profit</h3><p>${money(gross)}</p></div><div class="card"><h3>Expenses</h3><p>${money(ex)}</p></div><div class="card"><h3>Net Profit</h3><p>${money(net)}</p></div>`:''}</div><div class="grid2"><div class="card"><h3>Sales by Payment</h3>${pay.map(x=>`<p class="report-line"><span>${x[0]}</span><b>${money(x[1])}</b></p>`).join('')}</div><div class="card"><h3>Expense by Type</h3>${['Shop Rent','Electricity','Internet','Salary','Delivery','Repair','Marketing','Other'].map(t=>{const n=ee.filter(x=>x.type===t).reduce((a,x)=>a+x.amount,0);return n?`<p class="report-line"><span>${t}</span><b>${money(n)}</b></p>`:''}).join('')||'<div class="muted">No expenses</div>'}</div></div>${!admin()?'<div class="notice">Profit-sensitive financial figures are hidden for Sales Staff.</div>':''}`}
function tradein(){const rows=state.tradeins.slice().reverse().map((t,i)=>`<tr><td>${esc(t.date)}</td><td>${esc(t.customer)}</td><td>${esc(t.model)} ${esc(t.storage)}</td><td>${esc(t.imei)}</td><td>${esc(t.battery)}%</td><td>${money(t.buyPrice)}</td><td>${esc(t.condition)}</td><td>${admin()?`<button class="icon-btn" onclick="delTrade(${state.tradeins.indexOf(t)})">🗑️</button>`:''}</td></tr>`).join('');app.innerHTML=header('Trade-in / Buy-back','Buy old iPhones from customers and add them to stock',admin()?`<button class="primary" onclick="tradeForm()">＋ New Trade-in</button>`:'')+`<div class="table-wrap">${rows?`<table><thead><tr><th>Date</th><th>Customer</th><th>Phone</th><th>IMEI</th><th>Battery</th><th>Buy Price</th><th>Condition</th><th></th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No trade-in records yet.</div>'}</div>`}
function tradeForm(){if(!admin())return;openModal('Trade-in / Buy-back',`<form id="tf"><div class="form-grid"><label>Date<input name="date" type="date" required value="${today()}"></label><label>Customer Name<input name="customer" required></label><label>Customer Phone<input name="customerPhone"></label><label>Model<input name="model" required placeholder="iPhone 13 Pro"></label><label>Region<input name="region" placeholder="Yangon / Mandalay / ..."></label><label>Storage<select name="storage"><option>64GB</option><option>128GB</option><option>256GB</option><option>512GB</option><option>1TB</option></select></label><label>IMEI<input name="imei" required></label><label>Battery Health %<input name="battery" type="number" min="1" max="100" step="1" required></label><label>Condition<input name="condition" placeholder="9/10"></label><label>Box<select name="box"><option>ပါ</option><option>မပါ</option></select></label><label>Accessories<select name="accessories"><option>ပါ</option><option>မပါ</option></select></label><label>Buy Price (Ks)<input name="buyPrice" type="number" required></label><label>Note<input name="note"></label></div><button class="primary">Buy & Add to Stock</button></form>`);document.getElementById('tf').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.battery=batteryValue(x.battery);x.buyPrice=+x.buyPrice;x.id='TRD-'+Date.now();state.tradeins.push(x);state.phones.push({model:x.model,storage:x.storage,region:x.region||'',color:'',imei:x.imei,battery:x.battery,condition:x.condition,box:x.box,accessories:x.accessories,purchasePrice:x.buyPrice,sellingPrice:0,status:'In Stock'});upsertCustomer({customer:x.customer,customerPhone:x.customerPhone});save();closeModal();tradein()}}
function delTrade(i){if(confirm('Delete trade-in record? This will not automatically remove stock.')){state.tradeins.splice(i,1);save();tradein()}}
function warranty(){const rows=state.warranties.slice().reverse().map((w,i)=>`<tr><td>${esc(w.date)}</td><td>${esc(w.customer)}</td><td>${esc(w.imei)}</td><td>${esc(w.issue)}</td><td>${esc(w.status)}</td><td>${esc(w.resolution||'-')}</td><td>${admin()?`<button class="secondary small" onclick="warrantyForm(${state.warranties.indexOf(w)})">Edit</button> <button class="icon-btn" onclick="delWarranty(${state.warranties.indexOf(w)})">🗑️</button>`:''}</td></tr>`).join('');app.innerHTML=header('Warranty / Returns','Track customer warranty claims and returns',`<button class="primary" onclick="warrantyForm()">＋ Add Claim</button>`)+`<div class="table-wrap">${rows?`<table><thead><tr><th>Date</th><th>Customer</th><th>IMEI</th><th>Issue</th><th>Status</th><th>Resolution</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No warranty or return records.</div>'}</div>`}
function warrantyForm(i=null){const w=i==null?{}:state.warranties[i];openModal(i==null?'Add Warranty / Return':'Edit Warranty / Return',`<form id="wf"><div class="form-grid"><label>Date<input name="date" type="date" required value="${w.date||today()}"></label><label>Customer<input name="customer" value="${esc(w.customer)}"></label><label>Phone / IMEI<input name="imei" required value="${esc(w.imei)}"></label><label>Issue<input name="issue" required value="${esc(w.issue)}"></label><label>Status<select name="status">${['Open','Checking','Repaired','Replaced','Refunded','Closed'].map(x=>`<option ${w.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Resolution<input name="resolution" value="${esc(w.resolution)}"></label><label>Note<input name="note" value="${esc(w.note)}"></label></div><button class="primary">Save</button></form>`);document.getElementById('wf').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.id=w.id||'WAR-'+Date.now();if(i==null)state.warranties.push(x);else state.warranties[i]=x;save();closeModal();warranty()}}
function delWarranty(i){if(confirm('Delete claim?')){state.warranties.splice(i,1);save();warranty()}}
function users(){const rows=state.users.map((u,i)=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${i===0?'System Admin':admin()?`<button class="icon-btn" onclick="delUser(${i})">🗑️</button>`:''}</td></tr>`).join('');app.innerHTML=header('Users & Permissions','Admin controls and staff accounts',admin()?`<button class="primary" onclick="userForm()">＋ Add User</button>`:'')+`<div class="card"><p><b>Admin:</b> can manage stock, expenses, trade-ins, users and see profit.</p><p><b>Sales Staff:</b> can handle sales/customers and cannot see profit-sensitive figures.</p></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Name</th><th>Role</th><th></th></tr></thead><tbody><tr><td>admin</td><td>Administrator</td><td>admin</td><td>System Login</td></tr><tr><td>staff</td><td>Sales Staff</td><td>staff</td><td>System Login</td></tr>${rows}</tbody></table></div>`}
function userForm(){openModal('Add User',`<form id="uf"><div class="form-grid"><label>Username<input name="username" required></label><label>Name<input name="name" required></label><label>Password<input name="password" required></label><label>Role<select name="role"><option value="staff">Sales Staff</option><option value="admin">Admin</option></select></label></div><button class="primary">Create User</button></form>`);document.getElementById('uf').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(state.users.some(u=>u.username===x.username)||['admin','staff'].includes(x.username))return alert('Username already exists.');state.users.push(x);save();closeModal();users()}}
function delUser(i){if(confirm('Delete user?')){state.users.splice(i,1);save();users()}}
function backup(){app.innerHTML=header('Backup / Restore','Save your browser data as a JSON backup and restore it later',`<button class="primary" onclick="downloadBackup()">💾 Download Backup</button><button class="secondary" onclick="document.getElementById('restoreFile').click()">♻️ Restore Backup</button><input id="restoreFile" type="file" accept=".json" hidden>`)+`<div class="card"><p>Data is stored locally in this browser. Backup regularly before clearing browser data or moving to another computer.</p><p class="muted">This final file is an offline/local version; a real cloud database requires a backend.</p></div>`;document.getElementById('restoreFile').onchange=e=>e.target.files[0]&&restoreBackup(e.target.files[0])}
function downloadBackup(){const data={phones:state.phones,sales:state.sales,customers:state.customers,expenses:state.expenses,tradeins:state.tradeins,warranties:state.warranties,users:state.users,purchases:state.purchases,exportedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='i-Nation-Su-Backup-'+today()+'.json';a.click()}
async function restoreBackup(file){try{const d=JSON.parse(await file.text());['phones','sales','customers','expenses','tradeins','warranties','users','purchases'].forEach(k=>{if(Array.isArray(d[k]))state[k]=d[k]});save();render();alert('Restore completed.')}catch(e){alert('Backup file is invalid.')}}
function purchases(){
  const rows=state.purchases.slice().reverse().map((p,i)=>`<tr><td>${esc(p.date||'-')}</td><td>${esc(p.supplier||'-')}</td><td>${esc(p.model||'-')} ${esc(p.storage||'')}</td><td>${esc(p.imei||'-')}</td><td>${batteryDisplay(p.battery)}%</td><td>${money(p.purchasePrice||0)}</td><td>${esc(p.note||'-')}</td><td>${admin()?`<button class="secondary small" onclick="deletePurchase(${state.purchases.length-1-i})">🗑️ Delete</button>`:''}</td></tr>`).join('');
  app.innerHTML=header('Purchases','Supplier Purchase — supplier, purchase date and stock entry',`<button class="primary" onclick="supplierPurchaseForm()">＋ Supplier Purchase</button>`)+
  `<div class="card"><h3>Supplier Purchase</h3><p class="muted">Supplier ဆီက ဝယ်ယူထားတဲ့ iPhone တွေကို ဒီနေရာကနေ မှတ်တမ်းတင်ပြီး Inventory ထဲကို တစ်ခါတည်းထည့်နိုင်ပါတယ်။</p></div>`+
  `<div class="table-wrap">${rows?`<table><thead><tr><th>Date</th><th>Supplier</th><th>Model</th><th>IMEI</th><th>Battery</th><th>Purchase Price</th><th>Note</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="empty">Supplier Purchase မရှိသေးပါ။</div>`}</div>`;
}
function supplierPurchaseForm(){
  if(!admin())return alert('Supplier Purchase ထည့်ရန် Admin လိုအပ်ပါတယ်။');
  openModal('Supplier Purchase',`<form id="pf"><div class="form-grid"><label>Supplier<input name="supplier" required placeholder="Supplier name"></label><label>Purchase Date<input name="purchaseDate" type="date" required value="${today()}"></label><label>Model<input name="model" required placeholder="iPhone 13 Pro"></label><label>Storage<select name="storage"><option>64GB</option><option>128GB</option><option>256GB</option><option>512GB</option><option>1TB</option></select></label><label>Color<input name="color"></label><label>IMEI<input name="imei" required></label><label>Battery Health %<input name="battery" type="number" min="1" max="100" step="1" required></label><label>Condition<select name="condition"><option>10/10</option><option>9/10</option><option>8/10</option><option>7/10</option><option>6/10</option></select></label><label>Box<select name="box"><option>ပါ</option><option>မပါ</option></select></label><label>Accessories<select name="accessories"><option>ပါ</option><option>မပါ</option></select></label><label>Purchase Price (Ks)<input name="purchasePrice" type="number" min="0" required></label><label>Selling Price (Ks)<input name="sellingPrice" type="number" min="0" value="0"></label><label>Note<input name="note"></label></div><button class="primary">Save Purchase + Add Stock</button></form>`);
  document.getElementById('pf').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(state.phones.some(p=>String(p.imei).trim()===String(x.imei).trim()))return alert('ဒီ IMEI က Inventory ထဲမှာ ရှိပြီးသားပါ။');x.battery=batteryValue(x.battery);x.purchasePrice=+x.purchasePrice||0;x.sellingPrice=+x.sellingPrice||0;x.supplier=x.supplier.trim();x.purchaseDate=dateKey(x.purchaseDate||today())||today();x.id='PUR-'+Date.now();state.purchases.push({...x});state.phones.push({model:x.model,storage:x.storage,region:'',supplier:x.supplier,purchaseDate:x.purchaseDate,color:x.color||'',imei:x.imei.trim(),battery:x.battery,condition:x.condition,box:x.box,accessories:x.accessories,purchasePrice:x.purchasePrice,sellingPrice:x.sellingPrice,status:'In Stock'});save();closeModal();purchases()};
}
function deletePurchase(i){if(!admin())return;if(!state.purchases[i])return;if(confirm('ဒီ Supplier Purchase မှတ်တမ်းကို ဖျက်မလား?\nInventory Stock ကိုတော့ မဖျက်ပါ။')){state.purchases.splice(i,1);save();purchases()}}

function settings(){app.innerHTML=header('Settings','i-Nation Su system settings',`<button class="primary" onclick="invoiceEditor()">🧾 Custom Invoice Editor</button>`)+`<div class="grid2"><div class="card"><h3>Business</h3><p><b>${esc(invoiceSettings.shopName)}</b></p><p class="muted">iPhone Second-hand Shop Management System</p></div><div class="card"><h3>Data</h3><p>Storage: Browser localStorage</p><p>Currency: Myanmar Kyat (Ks)</p><p>Excel: SheetJS CDN</p></div></div>`}
function openModal(title,content){document.getElementById('modalTitle').textContent=title;document.getElementById('modalContent').innerHTML=content;modal.classList.remove('hidden')};function closeModal(){modal.classList.add('hidden')};document.getElementById('closeModal').onclick=closeModal;modal.onclick=e=>{if(e.target===modal)closeModal()}
function invoiceEditor(){const is=invoiceSettings;openModal('Custom Invoice Editor',`<form id="ief"><div class="form-grid"><label>Shop Name<input name="shopName" value="${esc(is.shopName)}" required></label><label>Invoice Subtitle<input name="subtitle" value="${esc(is.subtitle)}"></label><label>Phone<input name="phone" value="${esc(is.phone)}"></label><label>Address<input name="address" value="${esc(is.address)}"></label><label>Footer Text<input name="footer" value="${esc(is.footer)}"></label><label>Show Logo<select name="showLogo"><option value="1" ${is.showLogo?'selected':''}>Yes</option><option value="0" ${!is.showLogo?'selected':''}>No</option></select></label><label>Customer Phone<select name="showCustomerPhone"><option value="1" ${is.showCustomerPhone?'selected':''}>Show</option><option value="0" ${!is.showCustomerPhone?'selected':''}>Hide</option></select></label><label>IMEI<select name="showIMEI"><option value="1" ${is.showIMEI?'selected':''}>Show</option><option value="0" ${!is.showIMEI?'selected':''}>Hide</option></select></label><label>Payment<select name="showPayment"><option value="1" ${is.showPayment?'selected':''}>Show</option><option value="0" ${!is.showPayment?'selected':''}>Hide</option></select></label><label>Sales Person<select name="showSalesPerson"><option value="1" ${is.showSalesPerson?'selected':''}>Show</option><option value="0" ${!is.showSalesPerson?'selected':''}>Hide</option></select></label></div><button class="primary">Save Invoice Design</button></form>`);document.getElementById('ief').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));Object.assign(invoiceSettings,{shopName:f.shopName.trim(),subtitle:f.subtitle,phone:f.phone,address:f.address,footer:f.footer,showLogo:f.showLogo==='1',showCustomerPhone:f.showCustomerPhone==='1',showIMEI:f.showIMEI==='1',showPayment:f.showPayment==='1',showSalesPerson:f.showSalesPerson==='1'});saveInvoiceSettings();closeModal();alert('Invoice design saved.')}}
function openInvoiceById(id){const s=state.sales.find(x=>String(x.id)===String(id));if(!s)return;openInvoice(s)}
function openInvoice(s){const box=document.getElementById('invoicePrintArea');const im=document.getElementById('invoiceModal');if(!box||!im)return;const is=invoiceSettings;box.innerHTML=`<div class="invoice">${is.showLogo?`<div class="invoice-watermark"><img src="logo.png" alt=""></div><img class="invoice-logo" src="logo.png" alt="${esc(is.shopName)}">`:''}<div class="invoice-header"><div><div class="invoice-brand">${esc(is.shopName)}</div><div>${esc(is.subtitle)}</div>${is.phone?`<div>${esc(is.phone)}</div>`:''}${is.address?`<div>${esc(is.address)}</div>`:''}</div><div><b>Invoice No.</b><br>${esc(s.id)}<br><b>Date</b><br>${esc(s.date)}</div></div><hr><div class="customer-block"><b>Customer</b><br>${esc(s.customer||'Walk-in Customer')}${is.showCustomerPhone&&s.customerPhone?`<br>${esc(s.customerPhone)}`:''}${is.showSalesPerson?`<br><b>Sales Person:</b> ${esc(s.salesPerson||'-')}`:''}</div><div class="phone-detail"><b>Phone Detail</b><div class="phone-detail-grid"><span>Model: ${esc(s.model||'-')}</span><span>Storage: ${esc(s.storage||'-')}</span><span>Color: ${esc(s.color||'-')}</span><span>Battery: ${batteryDisplay(s.battery)}%</span><span>Condition: ${esc(s.condition||'-')}</span><span>Box: ${esc(s.box||'-')}</span><span>Accessories: ${esc(s.accessories||'-')}</span><span>IMEI: ${esc(s.imei||'-')}</span></div></div><table class="invoice-table"><thead><tr><th>Item</th>${is.showIMEI?'<th>IMEI</th>':''}<th>Qty</th><th>Amount</th></tr></thead><tbody><tr><td>${esc(s.model)} ${esc(s.storage||'')}</td>${is.showIMEI?`<td>${esc(s.imei)}</td>`:''}<td>1</td><td>${money(s.sellingPrice)}</td></tr></tbody></table><div class="invoice-total">Subtotal: ${money(s.sellingPrice)}<br>Discount: ${money(s.discount)}<br><strong>Total: ${money(s.finalPrice)}</strong></div>${is.showPayment?`<div class="payment-summary"><b>Payment:</b> ${esc(s.paymentType)}${s.paymentType!=='Installment'&&s.paymentDetail?` — ${esc(s.paymentDetail)}`:''}${s.paymentType!=='Installment'&&s.paymentNote?' ('+esc(s.paymentNote)+')':''}${(s.paymentType==='Installment'||s.paymentType==='Cash Down')?`<br><b>Deposit:</b> ${money(s.deposit||0)}`:''}${s.paymentType==='Installment'?`<br><b>Balance:</b> ${money(s.balance||0)}<br><b>Due Date:</b> ${esc(s.dueDate||'-')}`:''}</div>`:''}<div class="invoice-footer">${esc(is.footer)}${is.shopName?`<br>${esc(is.shopName)}`:''}</div></div>`;im.classList.remove('hidden');im.style.display='flex'};document.getElementById('previewPdfInvoice').onclick=async()=>{
  const src=document.getElementById('invoicePrintArea');
  const pm=document.getElementById('pdfPreviewModal'), fr=document.getElementById('pdfPreviewFrame');
  if(!src||!pm||!fr)return;
  if(!window.jspdf||!window.jspdf.jsPDF){alert('PDF library မတက်သေးပါ။ Internet ဖွင့်ပြီး ပြန်စမ်းပေးပါ။');return}
  const invoice=src.querySelector('.invoice');
  if(!invoice){alert('Invoice မတွေ့ပါ။');return}
  const text=(sel)=>{const el=invoice.querySelector(sel);return el?el.textContent.trim():''};
  const doc=new jspdf.jsPDF({unit:'mm',format:'a4'});
  const W=210, left=18, right=192;
  let y=18;
  // Watermark logo
  if(invoiceSettings.showLogo) try{
    const wm=new Image(); wm.src='logo.png';
    await new Promise((resolve,reject)=>{wm.onload=resolve;wm.onerror=reject});
    const wc=document.createElement('canvas'); wc.width=wm.naturalWidth||300; wc.height=wm.naturalHeight||100;
    wc.getContext('2d').drawImage(wm,0,0);
    const ratio=wc.width/wc.height, wh=95, ww=wh*ratio, wx=(210-ww)/2, wy=98;
    if(doc.setGState && doc.GState) doc.setGState(new doc.GState({opacity:0.08}));
    doc.addImage(wc.toDataURL('image/png'),'PNG',wx,wy,ww,wh);
    if(doc.setGState && doc.GState) doc.setGState(new doc.GState({opacity:1}));
  }catch(e){}
  // Logo (best effort)
  if(invoiceSettings.showLogo) try{
    const img=new Image();
    img.src='logo.png';
    await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject});
    const canvas=document.createElement('canvas');canvas.width=img.naturalWidth||300;canvas.height=img.naturalHeight||100;
    const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);
    const ratio=canvas.width/canvas.height; const h=16, w=h*ratio;
    doc.addImage(canvas.toDataURL('image/png'),'PNG',left,y,w,h); y+=19;
  }catch(e){doc.setFontSize(18);doc.setFont('helvetica','bold');doc.text(invoiceSettings.shopName,left,y);y+=10}
  doc.setFontSize(9);doc.setFont('helvetica','normal');doc.text(invoiceSettings.subtitle,left,y);y+=8;
  doc.setFontSize(10);doc.setFont('helvetica','bold');doc.text('Invoice No.',150,22);doc.setFont('helvetica','normal');doc.text(text('.invoice-header > div:last-child').split('Invoice No.')[1]?.split('Date')[0]?.trim()||'',150,28);
  const dateText=text('.invoice-header > div:last-child'); const dm=dateText.match(/Date\s*([\s\S]*)$/); if(dm){doc.setFont('helvetica','bold');doc.text('Date',150,34);doc.setFont('helvetica','normal');doc.text(dm[1].trim(),150,40)}
  doc.line(left,y,W-right+18,y);y+=9;
  const customer=invoice.querySelector('.customer-block')?.innerText||'';
  const cLines=customer.split('\n').filter(Boolean);
  doc.setFont('helvetica','bold');doc.text('Customer',left,y);y+=5;doc.setFont('helvetica','normal');cLines.slice(1).forEach(line=>{doc.text(line,left,y);y+=5});y+=5;
  const detail=invoice.querySelector('.phone-detail')?.innerText||'';
  if(detail){doc.setFont('helvetica','bold');doc.text('Phone Detail',left,y);y+=5;doc.setFont('helvetica','normal');detail.split('\n').filter(Boolean).slice(1).forEach(line=>{doc.text(line,left,y);y+=5});y+=4;}
  // Item table
  doc.setFont('helvetica','bold');doc.text('Item',left,y);doc.text('IMEI',82,y);doc.text('Qty',142,y);doc.text('Amount',165,y);y+=3;doc.line(left,y,192,y);y+=6;
  const row=invoice.querySelector('.invoice-table tbody tr');
  if(row){const cells=[...row.children].map(x=>x.textContent.trim());doc.setFont('helvetica','normal');doc.text(cells[0]||'',left,y);doc.text(cells[1]||'',82,y);doc.text(cells[2]||'1',142,y);doc.text(cells[3]||'',165,y);y+=8}
  doc.line(left,y,192,y);y+=9;
  const totalText=invoice.querySelector('.invoice-total')?.innerText||'';
  const totalLines=totalText.split('\n').filter(Boolean);
  doc.setFont('helvetica','normal');totalLines.forEach((line,i)=>{doc.text(line,165,y,{align:'left'});y+=6});
  const pay=invoice.querySelector('.payment-summary')?.innerText||'';y+=5;doc.setFont('helvetica','bold');doc.text('Payment',left,y);doc.setFont('helvetica','normal');doc.text(pay.replace(/^Payment:\s*/i,''),left+25,y,{maxWidth:145});y+=12;
  doc.setFontSize(9);doc.text(invoiceSettings.footer,left,275);doc.text(invoiceSettings.shopName,left,281);
  const blob=doc.output('blob');
  if(window.__invoicePdfUrl)URL.revokeObjectURL(window.__invoicePdfUrl);
  window.__invoicePdfUrl=URL.createObjectURL(blob);
  fr.src=window.__invoicePdfUrl;
  pm.classList.remove('hidden');pm.style.display='flex';
  const dl=document.getElementById('downloadPdfInvoice'); if(dl)dl.onclick=()=>{const a=document.createElement('a');a.href=window.__invoicePdfUrl;a.download='Invoice.pdf';a.click()};
};
document.getElementById('closePdfPreview').onclick=()=>{const pm=document.getElementById('pdfPreviewModal');pm.classList.add('hidden');pm.style.display='none'};
document.getElementById('printInvoice').onclick=()=>window.print();document.getElementById('closeInvoice').onclick=()=>{const im=document.getElementById('invoiceModal');im.classList.add('hidden');im.style.display='none'};
function barcodeLabel(p){return `<div class="barcode-label"><div class="barcode-model">${esc(p.model)} ${esc(p.storage||'')}</div><svg class="barcode-svg" data-code="${esc(p.imei)}"></svg><div class="barcode-imei">${esc(p.imei)}</div><div class="barcode-meta">Battery: ${batteryDisplay(p.battery)}%</div></div>`}
function printBarcode(i){const p=state.phones[i];if(!p)return;printBarcodeItems([p])}
function printAllBarcodes(){const stock=state.phones.filter(p=>(p.status||'In Stock')==='In Stock');if(!stock.length)return alert('In Stock ဖုန်းမရှိသေးပါ။');if(!confirm(`${stock.length} ခုသော In Stock Sticker များကို Print ထုတ်မလား?`))return;printBarcodeItems(stock)}
function printBarcodeItems(items){const w=window.open('','_blank','width=500,height=700');if(!w)return alert('Popup blocked ဖြစ်နေပါတယ်။ Browser မှာ Pop-up ကို Allow လုပ်ပေးပါ။');const labels=items.map(barcodeLabel).join('');w.document.write(`<!doctype html><html><head><meta charset="UTF-8"><title>Barcode Stickers</title><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script><style>@page{size:40mm 30mm;margin:0}html,body{margin:0;padding:0;background:#fff}.sheet{width:40mm}.barcode-label{width:40mm;height:30mm;box-sizing:border-box;padding:1.6mm 1.4mm;text-align:center;font-family:Arial,'Noto Sans Myanmar',sans-serif;overflow:hidden;page-break-after:always}.barcode-brand{font-size:10pt;font-weight:800;line-height:1.1}.barcode-model{font-size:8.5pt;font-weight:700;margin-top:1mm;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.barcode-svg{width:36mm;height:11mm;display:block;margin:1mm auto 0}.barcode-imei{font-size:7pt;letter-spacing:.3px;margin-top:.2mm}.barcode-meta{font-size:6.2pt;margin-top:1mm;white-space:nowrap}.barcode-label:last-child{page-break-after:auto}@media screen{body{display:flex;justify-content:flex-start}.barcode-label{outline:1px dashed #bbb}}</style></head><body><div class="sheet">${labels}</div><script>window.onload=()=>{document.querySelectorAll('.barcode-svg').forEach(el=>JsBarcode(el,el.dataset.code,{format:'CODE128',displayValue:false,margin:0,width:1.35,height:34}));setTimeout(()=>window.print(),500)}<\/script></body></html>`);w.document.close()}
function exportInventory(){if(!window.XLSX)return alert('Excel library မတက်သေးပါ။');const rows=state.phones.map(p=>({'Model':p.model,'Storage':p.storage,'Region':p.region||'','Supplier':p.supplier||'','Purchase Date':p.purchaseDate||'','Color':p.color,'IMEI':p.imei,'Battery Health':Math.round(Number(p.battery)||0),'Condition':p.condition,'Box':p.box,'Accessories':p.accessories,'Purchase Price':p.purchasePrice,'Selling Price':p.sellingPrice,'Status':p.status}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Inventory');XLSX.writeFile(wb,'i-Nation-Su-Inventory.xlsx')}
function templateInventory(){if(!window.XLSX)return;const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{'Model':'iPhone 13 Pro','Storage':'256GB','Region':'Yangon','Supplier':'Sample Supplier','Purchase Date':today(),'Color':'Sierra Blue','IMEI':'351234567890123','Battery Health':87,'Condition':'9/10','Box':'ပါ','Accessories':'ပါ','Purchase Price':1200000,'Selling Price':1350000,'Status':'In Stock'}]),'Inventory');XLSX.writeFile(wb,'i-Nation-Su-Inventory-Template.xlsx')}
async function importInventory(file){if(!window.XLSX)return;const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),rs=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});const existing=new Set(state.phones.map(p=>p.imei));let n=0;rs.forEach(r=>{const p={model:String(r.Model||'').trim(),storage:String(r.Storage||'').trim(),region:String(r.Region||r.RegionName||'').trim(),supplier:String(r.Supplier||r['Supplier Name']||'').trim(),purchaseDate:dateKey(r['Purchase Date']!==undefined&&r['Purchase Date']!==''?r['Purchase Date']:r.PurchaseDate),color:String(r.Color||''),imei:String(r.IMEI||'').trim(),battery:batteryValue(r['Battery Health']!==undefined&&r['Battery Health']!==''?r['Battery Health']:r.Battery),condition:String(r.Condition||''),box:String(r.Box||''),accessories:String(r.Accessories||''),purchasePrice:+(r['Purchase Price']||r['Buy Price']||0),sellingPrice:+(r['Selling Price']||r['Sell Price']||0),status:String(r.Status||'In Stock')};if(p.model&&p.imei&&!existing.has(p.imei)){state.phones.push(p);existing.add(p.imei);n++}});save();inventory();alert('Import completed: '+n+' new phone(s).')}
function exportReport(){if(!window.XLSX)return alert('Excel library မတက်သေးပါ။');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(state.sales),'Sales');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(state.expenses),'Expenses');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(state.tradeins),'Trade-in');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(state.warranties),'Warranty');XLSX.writeFile(wb,'i-Nation-Su-Reports.xlsx')}
function reportData(){const r=range(),ss=state.sales.filter(s=>inRange(s.dateISO||s.date,r)),ee=state.expenses.filter(e=>inRange(e.date,r)),salesTotal=ss.reduce((a,s)=>a+Number(s.finalPrice||0),0),cost=ss.reduce((a,s)=>a+Number(s.purchasePrice||0),0),gross=salesTotal-cost,ex=ee.reduce((a,x)=>a+Number(x.amount||0),0),net=gross-ex;return {r,ss,ee,salesTotal,cost,gross,ex,net}}
function exportReportPDF(){
  if(!window.jspdf||!window.jspdf.jsPDF)return alert('PDF library မတက်သေးပါ။ Internet ဖွင့်ပြီး ပြန်စမ်းပေးပါ။');
  const d=reportData(), doc=new jspdf.jsPDF({unit:'mm',format:'a4'}), W=210, margin=16;
  doc.addImage(LOGO_DATA,'PNG',margin,10,24,24);
  doc.setFontSize(20);doc.setFont(undefined,'bold');doc.text('i-Nation Su',45,18);
  doc.setFontSize(11);doc.setFont(undefined,'normal');doc.text('Second-hand iPhone Shop — Financial Report',45,25);
  doc.setFontSize(9);doc.text('Period: '+(d.r.from||'All')+' to '+(d.r.to||'All'),45,31);
  doc.setDrawColor(180);doc.line(margin,38,W-margin,38);
  let y=48;
  const row=(label,value)=>{doc.setFontSize(11);doc.setFont(undefined,'normal');doc.text(label,margin,y);doc.setFont(undefined,'bold');doc.text(money(value),W-margin,y,{align:'right'});y+=9};
  row('Total Sales',d.salesTotal);
  if(admin()){row('Purchase Cost',d.cost);row('Gross Profit',d.gross);row('Total Expenses',d.ex);row('Net Profit',d.net);}
  y+=3;doc.setFont(undefined,'bold');doc.setFontSize(13);doc.text('Sales by Payment',margin,y);y+=8;
  ['Cash','MMQR','Banking','MPU'].forEach(p=>{const v=d.ss.filter(s=>s.paymentType===p).reduce((a,s)=>a+Number(s.finalPrice||0),0);row('  '+p,v)});
  y+=3;doc.setFontSize(13);doc.setFont(undefined,'bold');doc.text('Expense by Type',margin,y);y+=8;
  ['Shop Rent','Electricity','Internet','Salary','Delivery','Repair','Marketing','Other'].forEach(t=>{const v=d.ee.filter(x=>x.type===t).reduce((a,x)=>a+Number(x.amount||0),0);if(v)row('  '+t,v)});
  y+=4;doc.setFontSize(9);doc.setFont(undefined,'normal');doc.text('Generated: '+new Date().toLocaleString(),margin,285);
  doc.save('i-Nation-Su-Report-'+today()+'.pdf');
}
function login(){const u=document.getElementById('loginUser').value.trim().toLowerCase(),p=document.getElementById('loginPass').value;let user=null;if(u==='admin'&&p==='1234')user={username:'admin',name:'Administrator',role:'admin'};else if(u==='staff'&&p==='1234')user={username:'staff',name:'Sales Staff',role:'staff'};else{const x=state.users.find(x=>x.username===u&&x.password===p);if(x)user={username:x.username,name:x.name,role:x.role}}if(!user)return document.getElementById('loginError').textContent='Username သို့မဟုတ် Password မှားနေပါတယ်။';state.user=user;sessionStorage.setItem('nationSuUser',JSON.stringify(user));document.getElementById('loginError').textContent='';render()}
document.getElementById('loginBtn').onclick=login;document.getElementById('loginPass').onkeydown=e=>e.key==='Enter'&&login();document.getElementById('loginScreen').addEventListener('click',e=>{if(e.target.id==='loginUser'||e.target.id==='loginPass')e.target.focus()});const out=document.createElement('button');out.className='nav-btn logout';out.textContent='🚪 Logout';out.onclick=()=>{state.user=null;sessionStorage.removeItem('nationSuUser');shell()};document.querySelector('.sidebar').appendChild(out);
if(!state.users.length){state.users=[{username:'manager',name:'Manager',password:'1234',role:'admin'}];save()}render();
